SELECT 
FROM mt_power_recharge
WHERE shop_id = #{shopId}

    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

ORDER BY id DESC

SELECT FROM mt_power_recharge src LEFT JOIN mt_shop shop ON shop.id = src.shop_id LEFT JOIN ai_user u ON u.user_id = src.sales_user_id WHERE 1 = 1
AND ( src.recharge_no LIKE CONCAT('%', #{keyword}, '%') OR src.payment_order_no LIKE CONCAT('%', #{keyword}, '%') OR src.transaction_id LIKE CONCAT('%', #{keyword}, '%') OR src.redemption_code LIKE CONCAT('%', #{keyword}, '%') OR src.sales_user_phone LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(u.nickname, u.username, src.sales_user_id) LIKE CONCAT('%', #{keyword}, '%') OR shop.poi_id LIKE CONCAT('%', #{keyword}, '%') OR shop.epoi_id LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(shop.poi_name, shop.name) LIKE CONCAT('%', #{keyword}, '%') )
AND src.pay_status = #{payStatus}
AND src.create_time >= #{startTime}
AND src.create_time <= #{endTime}
ORDER BY src.id DESC
